import test from 'node:test';import assert from 'node:assert/strict';
import {HERO_TRANSFORMATIONS,normalizeHeroLegacies,validHeroLegacies,recordLegacyDeed,equipLegacy,legacySummary,syncHeroLegacies,copyHeroLegacy,prepareLegacyBattle,validLegacyBattle,legacyActions,legacyCommand,advanceLegacyBattle,legacyAllowsTool,modifyLegacyDamage,interceptLegacyHit} from '../hero-legacy.js';
import {defaultHero} from '../mako.js';
import {joinJourney,journeyWeave} from '../journey-roster.js';
const state=()=>({mode:'field',party:[0],recruited:[0],heroes:Array.from({length:7},(_,id)=>defaultHero(id)),items:{ether:0},gold:37,flags:{kept:1}});
function grant(s,id,form){const e=({'ceramic-arm':{kind:'objective',goal:'regulator'},'reed-ear':{kind:'objective',goal:'escort'},'ash-shadow':{kind:'knowledge',goal:'rhythm'}})[form];return recordLegacyDeed(s,{id:form+':'+id,heroId:id,success:true,label:'A visible deed',...e});}
function battle(form,heroId=0){const s=state();grant(s,heroId,form);assert.equal(equipLegacy(s,heroId,form),true);const h=s.heroes[heroId];Object.assign(h,{x:1.5,y:1.5,atb:1,status:{}});const enemy={id:'e0',name:'Copper bell creature',x:4.5,y:1.5,hp:100,intent:{kind:'strike',shape:'single',target:heroId,x:h.x,y:h.y,left:1,total:1,label:'Charged note'}};const b={context:{heroLegacies:s.heroLegacies,walkable:[[0,1],[1,1],[2,1],[3,1],[4,1]]},heroes:[h],enemies:[enemy],time:0,event(){}};prepareLegacyBattle(b);return{b,h,enemy,s};}
test('all seven leads can earn all three optional forms from distinct actual outcome classes',()=>{for(let id=0;id<7;id++){const s=state();for(const form of HERO_TRANSFORMATIONS){const result=grant(s,id,form.id);assert.equal(result.unlocked,form.id);}assert.deepEqual(new Set(s.heroLegacies.heroes[id].unlocked),new Set(HERO_TRANSFORMATIONS.map(t=>t.id)));assert.equal(s.heroLegacies.heroes[id].equipped,null);assert.equal(validHeroLegacies(s.heroLegacies),true);assert.equal(s.heroes[id].power,defaultHero(id).power);}});
test('failed, unknown, repeated and malformed events do not farm rewards or body history',()=>{const s=state();assert.equal(recordLegacyDeed(s,{id:'loss',heroId:0,kind:'objective',goal:'regulator',success:false}).added,false);assert.equal(recordLegacyDeed(s,{id:'unknown',heroId:0,kind:'talk'}).added,false);assert.equal(recordLegacyDeed(s,{id:'wrong',heroId:7,kind:'knowledge'}).added,false);assert.equal(grant(s,0,'ceramic-arm').added,true);assert.equal(grant(s,0,'ceramic-arm').added,false);assert.equal(s.heroLegacies.heroes[0].deeds.length,1);assert.equal(s.gold,37);assert.equal(s.items.ether,0);});
test('first attunement is free and subsequent changes pay exactly one Ether between encounters',()=>{const s=state();grant(s,0,'ceramic-arm');grant(s,0,'reed-ear');assert.equal(equipLegacy(s,0,'ceramic-arm'),true);assert.equal(s.heroes[0].legacy.transformation,'ceramic-arm');assert.equal(equipLegacy(s,0,null),true);assert.equal(s.heroes[0].legacy,null);assert.equal(equipLegacy(s,0,'reed-ear'),false);s.items.ether=1;assert.equal(equipLegacy(s,0,'reed-ear'),true);assert.equal(s.items.ether,0);s.mode='battle';assert.equal(equipLegacy(s,0,null),false);s.mode='dialog';assert.equal(equipLegacy(s,0,null),false);});
test('persistent histories are bounded, serialized and reject unearned or malformed forms',()=>{const s=state();for(let n=0;n<200;n++)recordLegacyDeed(s,{id:'discovery-'+n,heroId:0,kind:'knowledge',success:true});assert.equal(s.heroLegacies.settled.length,128);assert.equal(s.heroLegacies.heroes[0].deeds.length,32);assert.equal(validHeroLegacies(JSON.parse(JSON.stringify(s.heroLegacies))),true);const bad=structuredClone(s.heroLegacies);bad.heroes[0].equipped='ceramic-arm';assert.equal(validHeroLegacies(bad),false);bad.heroes[0].equipped=null;bad.heroes[0].deeds[0].id=5;assert.equal(validHeroLegacies(bad),false);assert.equal(validHeroLegacies(normalizeHeroLegacies(bad)),true);});
test('a remembered signature and a deed travel with the selected local companion, never currency or campaign flags',()=>{const source=state(),target=state();grant(source,6,'reed-ear');recordLegacyDeed(source,{id:'signal',heroId:6,kind:'objective',goal:'signal',success:true,pattern:{id:'moth-line',name:'Moonveil refrain',kind:'strike',shape:'line',family:'moonmoth'}});equipLegacy(source,6,'reed-ear');source.gold=999;copyHeroLegacy(target,source,6);assert.equal(target.gold,37);assert.deepEqual(target.flags,{kept:1});assert.equal(target.heroes[6].legacy.transformation,'reed-ear');assert.equal(legacySummary(target,6).signature,'Moonveil refrain');assert.equal(source.items.ether,0);assert.equal(validHeroLegacies(target.heroLegacies),true);});
test('ceramic anchor costs readiness and MP, blocks one real crossing, and releases the tool hand',()=>{const {b,h,enemy}=battle('ceramic-arm');const before=h.mp;assert.equal(legacyActions(b,h,enemy)[0].enabled,true);assert.equal(legacyCommand(b,h,enemy,{action:'anchor'}),true);assert.equal(h.atb,0);assert.equal(h.mp,before-5);assert.equal(legacyAllowsTool(b,h),false);assert.equal(interceptLegacyHit(b,enemy,enemy.intent,h),true);assert.equal(legacyAllowsTool(b,h),true);assert.equal(interceptLegacyHit(b,enemy,enemy.intent,h),false);h.atb=1;h.fieldGear='a-jar';assert.equal(legacyCommand(b,h,enemy,{action:'anchor'}),false);assert.equal(h.atb,1);});
test('ceramic cover bypasses close contact and expires without trapping the tool hand',()=>{const {b,h,enemy}=battle('ceramic-arm');legacyCommand(b,h,enemy,{action:'anchor'});enemy.x=2;assert.equal(interceptLegacyHit(b,enemy,enemy.intent,h),false);b.time=13;advanceLegacyBattle(b,.1);assert.equal(legacyAllowsTool(b,h),true);assert.equal(b.legacy.anchors[0].charges,0);});
test('reed ear reads a real windup once and pays for it; electrical sensitivity is a real tradeoff',()=>{const {b,h,enemy}=battle('reed-ear');assert.equal(legacyCommand(b,h,enemy,{action:'listen'}),true);assert.equal(enemy.intent.left,1.8);assert.equal(enemy.intent.total,1.8);assert.equal(h.mp,33);h.atb=1;assert.equal(legacyCommand(b,h,enemy,{action:'listen'}),false);assert.equal(h.atb,1);assert.ok(Math.abs(modifyLegacyDamage(b,enemy,h,100,{core:'volt'})-115)<1e-10);assert.equal(modifyLegacyDamage(b,enemy,h,100,{core:'flame'}),100);});
test('ash step follows actual adjacent floor, leaves exposure and catches only an attack aimed at the previous place',()=>{const {b,h,enemy}=battle('ash-shadow');b.context.walkable=[[0,1],[1,1]];assert.equal(legacyCommand(b,h,enemy,{action:'ash-step'}),true);assert.deepEqual([h.x,h.y],[.5,1.5]);assert.equal(h.mp,31);assert.equal(h.status.exposed,5);assert.equal(interceptLegacyHit(b,enemy,{...enemy.intent,x:4,y:4},h),false);assert.equal(interceptLegacyHit(b,enemy,enemy.intent,h),true);assert.equal(interceptLegacyHit(b,enemy,enemy.intent,h),false);});
test('no ash movement crosses a wall, unavailable topology or an occupied destination',()=>{const {b,h,enemy}=battle('ash-shadow');b.context.walkable=[[1,1]];assert.equal(legacyCommand(b,h,enemy,{action:'ash-step'}),false);assert.equal(h.atb,1);delete b.context.walkable;assert.equal(legacyCommand(b,h,enemy,{action:'ash-step'}),false);b.context.walkable=[[1,1],[2,1]];b.enemies[0].x=2.5;assert.equal(legacyCommand(b,h,enemy,{action:'ash-step'}),false);});
test('runtime snapshots preserve spent uses and reject mismatched owners, excessive counts and unearned forms',()=>{const {b,h,enemy}=battle('ceramic-arm');legacyCommand(b,h,enemy,{action:'anchor'});const value=structuredClone(b.legacy);assert.equal(validLegacyBattle(value,b.heroes),true);assert.equal(value.heroes[0].uses,1);value.anchors[0].ownerId=6;assert.equal(validLegacyBattle(value,b.heroes),false);value.anchors[0].ownerId=0;value.heroes[0].equipped='ash-shadow';assert.equal(validLegacyBattle(value,b.heroes),false);value.heroes[0].equipped='ceramic-arm';value.heroes[0].uses=3;assert.equal(validLegacyBattle(value,b.heroes),false);});
test('ceramic physical tradeoff is paid without mutating the base stat sheet',()=>{const {b,h,enemy}=battle('ceramic-arm');const power=h.power;assert.equal(modifyLegacyDamage(b,h,enemy,100,{physical:true}),90);assert.equal(modifyLegacyDamage(b,h,enemy,100,{physical:false}),100);assert.equal(h.power,power);h.mp=0;assert.equal(legacyCommand(b,h,enemy,{action:'anchor'}),false);assert.equal(h.atb,1);});

test('real local drop-in preserves the invited body history without importing levels or wealth',()=>{const target=state(),source=state();Object.assign(target,{schema:'ash-aether.engine2/1',chapter:3,cores:['earth'],supports:['focus'],story:{slots:1,journal:[]}});Object.assign(source,{schema:'ash-aether.engine2/1',chapter:3,party:[6],recruited:[6],journey:journeyWeave(6,0)});grant(source,6,'ash-shadow');equipLegacy(source,6,'ash-shadow');source.gold=9000;source.heroes[6]=Object.assign(defaultHero(6,45),{legacy:{transformation:'ash-shadow'}});const profile={hero:6,savedAt:1,value:{schema:'ash-aether.enhanced-save/1',world:source}};assert.equal(joinJourney(target,profile).joined,true);assert.equal(target.heroes[6].legacy.transformation,'ash-shadow');assert.equal(target.heroLegacies.heroes[6].deeds.length,1);assert.equal(target.heroes[6].level,1);assert.equal(target.gold,37);assert.deepEqual(target.party,[0,6]);});
